        CONSTRAINT [FK_Families_ApplicationUsers_CreatedByApplicationUserId] FOREIGN KEY ([CreatedByApplicationUserId]) REFERENCES [ApplicationUsers] ([Id]) ON DELETE NO ACTION
    );
');
