IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908145353_Phase5PatientFamilyFoundation'
)
BEGIN
    EXEC(N'    CREATE TABLE [PatientAccountLinks] (
        [Id] uniqueidentifier NOT NULL,
        [ApplicationUserId] uniqueidentifier NOT NULL,
        [PatientId] uniqueidentifier NOT NULL,
        [Source] int NOT NULL,
        [VerifiedOnUtc] datetime2 NOT NULL,
        [CreatedOnUtc] datetime2 NOT NULL,
        CONSTRAINT [PK_PatientAccountLinks] PRIMARY KEY ([Id]),
        CONSTRAINT [FK_PatientAccountLinks_ApplicationUsers_ApplicationUserId] FOREIGN KEY ([ApplicationUserId]) REFERENCES [ApplicationUsers] ([Id]) ON DELETE NO ACTION,
        CONSTRAINT [FK_PatientAccountLinks_Patients_PatientId] FOREIGN KEY ([PatientId]) REFERENCES [Patients] ([Id]) ON DELETE NO ACTION
    );
');
END;

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908145353_Phase5PatientFamilyFoundation'
)
BEGIN
    EXEC(N'    IF EXISTS (
        SELECT 1
        FROM [Patients] AS [p]
        LEFT JOIN [ApplicationUsers] AS [u] ON [u].[Id] = [p].[ApplicationUserId]
        WHERE [u].[Id] IS NULL)
        THROW 51000, ''Legacy Patient data contains an invalid ApplicationUserId.'', 1;

    IF EXISTS (
        SELECT [ApplicationUserId]
        FROM [Patients]
        GROUP BY [ApplicationUserId]
        HAVING COUNT_BIG(*) > 1)
        THROW 51001, ''Legacy Patient data violates account-link cardinality.'', 1;

    UPDATE [p]
    SET [p].[PhoneNumber] = [u].[PhoneNumber],
        [p].[Email] = [u].[Email]
    FROM [Patients] AS [p]
    INNER JOIN [ApplicationUsers] AS [u] ON [u].[Id] = [p].[ApplicationUserId];

    INSERT INTO [PatientAccountLinks]
        ([Id], [ApplicationUserId], [PatientId], [Source], [VerifiedOnUtc], [CreatedOnUtc])
    SELECT NEWID(), [p].[ApplicationUserId], [p].[Id], 1, [p].[CreatedOnUtc], [p].[CreatedOnUtc]
    FROM [Patients] AS [p];
');
END;

