    WHERE [MigrationId] = N'20260908145353_Phase5PatientFamilyFoundation'
)
BEGIN
    EXEC(N'    DECLARE @var nvarchar(max);
    SELECT @var = QUOTENAME([d].[name])
    FROM [sys].[default_constraints] [d]
    INNER JOIN [sys].[columns] [c] ON [d].[parent_column_id] = [c].[column_id] AND [d].[parent_object_id] = [c].[object_id]
    WHERE ([d].[parent_object_id] = OBJECT_ID(N''[Patients]'') AND [c].[name] = N''ApplicationUserId'');
    IF @var IS NOT NULL EXEC(N''ALTER TABLE [Patients] DROP CONSTRAINT '' + @var + '';'');
    ALTER TABLE [Patients] DROP COLUMN [ApplicationUserId];
');
END;

