        [CreatedByApplicationUserId] uniqueidentifier NULL,
        [ModifiedByApplicationUserId] uniqueidentifier NULL,
        [Revision] int NOT NULL,
        [RowVersion] rowversion NOT NULL,
        CONSTRAINT [PK_DrugCatalogs] PRIMARY KEY ([Id]),
        CONSTRAINT [CK_DrugCatalogs_Merge] CHECK (([Status] = 4 AND [MergedIntoDrugCatalogId] IS NOT NULL AND [MergedIntoDrugCatalogId] <> [Id]) OR ([Status] <> 4 AND [MergedIntoDrugCatalogId] IS NULL)),
        CONSTRAINT [CK_DrugCatalogs_Price] CHECK ([PriceEgp] IS NULL OR [PriceEgp] >= 0),
        CONSTRAINT [CK_DrugCatalogs_Status] CHECK ([Status] IN (1,2,3,4)),
        CONSTRAINT [FK_DrugCatalogs_ApplicationUsers_CreatedByApplicationUserId] FOREIGN KEY ([CreatedByApplicationUserId]) REFERENCES [ApplicationUsers] ([Id]) ON DELETE NO ACTION,
        CONSTRAINT [FK_DrugCatalogs_ApplicationUsers_ModifiedByApplicationUserId] FOREIGN KEY ([ModifiedByApplicationUserId]) REFERENCES [ApplicationUsers] ([Id]) ON DELETE NO ACTION,
        CONSTRAINT [FK_DrugCatalogs_DrugCatalogImportBatches_MissingFromSourceSinceBatchId] FOREIGN KEY ([MissingFromSourceSinceBatchId]) REFERENCES [DrugCatalogImportBatches] ([Id]) ON DELETE NO ACTION,
        CONSTRAINT [FK_DrugCatalogs_DrugCatalogImportBatches_OriginImportBatchId] FOREIGN KEY ([OriginImportBatchId]) REFERENCES [DrugCatalogImportBatches] ([Id]) ON DELETE NO ACTION,
        CONSTRAINT [FK_DrugCatalogs_DrugCatalogRequests_OriginDrugCatalogRequestId] FOREIGN KEY ([OriginDrugCatalogRequestId]) REFERENCES [DrugCatalogRequests] ([Id]) ON DELETE NO ACTION,
        CONSTRAINT [FK_DrugCatalogs_DrugCatalogs_MergedIntoDrugCatalogId] FOREIGN KEY ([MergedIntoDrugCatalogId]) REFERENCES [DrugCatalogs] ([Id]) ON DELETE NO ACTION
    );
