        CONSTRAINT [FK_PrescriptionItems_DrugCatalogs_DrugCatalogId] FOREIGN KEY ([DrugCatalogId]) REFERENCES [DrugCatalogs] ([Id]) ON DELETE NO ACTION,
        CONSTRAINT [FK_PrescriptionItems_PrescriptionVersions_PrescriptionVersionId] FOREIGN KEY ([PrescriptionVersionId]) REFERENCES [PrescriptionVersions] ([Id])
    );
