        [RequestedAtUtc] datetime2 NULL,
        [Revision] int NOT NULL,
        [RowVersion] rowversion NOT NULL,
        CONSTRAINT [PK_LabRequests] PRIMARY KEY ([Id]),
        CONSTRAINT [CK_LabRequests_PostVisit] CHECK ([Origin] = 1 OR ([PostVisitReason] IS NOT NULL AND [Status] <> 1)),
        CONSTRAINT [CK_LabRequests_State] CHECK ([Status] IN (1,2,3,4,5) AND [Origin] IN (1,2)),
