    EXEC(N'    CREATE TRIGGER [TR_NoDelete_OperatingFinancialPlans] ON [OperatingFinancialPlans] INSTEAD OF DELETE AS THROW 51018, ''Phase 18 records cannot be deleted.'', 1;
